    p19.[StatusCode] AS [SupplierTier_RecordStatus_StatusCode],
    p19.[StatusName] AS [SupplierTier_RecordStatus_StatusName]
FROM [dim].[Supplier] b
LEFT JOIN [ref].[Currency] p1 ON b.[CurrencyKey] = p1.[CurrencyKey]
LEFT JOIN [ref].[CurrencyRegion] p2 ON p1.[CurrencyRegionKey] = p2.[CurrencyRegionKey]
LEFT JOIN [ref].[IncotermCode] p3 ON b.[IncotermCodeKey] = p3.[IncotermCodeKey]
LEFT JOIN [ref].[PaymentTerm] p4 ON b.[PaymentTermKey] = p4.[PaymentTermKey]
LEFT JOIN [ref].[RecordStatus] p5 ON b.[RecordStatusKey] = p5.[RecordStatusKey]
LEFT JOIN [ref].[SupplierQualificationStatus] p6 ON b.[SupplierQualificationStatusKey] = p6.[SupplierQualificationStatusKey]
LEFT JOIN [dim].[GeoPostalCode] p7 ON b.[GeoPostalCodeKey] = p7.[GeoPostalCodeKey]
LEFT JOIN [dim].[GeoCity] p8 ON p7.[GeoCityKey] = p8.[GeoCityKey]
LEFT JOIN [dim].[GeoStateProvince] p9 ON p8.[GeoStateProvinceKey] = p9.[GeoStateProvinceKey]
LEFT JOIN [dim].[GeoCountry] p10 ON p9.[GeoCountryKey] = p10.[GeoCountryKey]
LEFT JOIN [dim].[GeoContinent] p11 ON p10.[GeoContinentKey] = p11.[GeoContinentKey]
LEFT JOIN [dim].[SupplierCategory] p12 ON b.[SupplierCategoryKey] = p12.[SupplierCategoryKey]
LEFT JOIN [ref].[PaymentTerm] p13 ON p12.[PaymentTermKey] = p13.[PaymentTermKey]
LEFT JOIN [ref].[RecordStatus] p14 ON p12.[RecordStatusKey] = p14.[RecordStatusKey]
LEFT JOIN [dim].[SupplierRiskClass] p15 ON b.[SupplierRiskClassKey] = p15.[SupplierRiskClassKey]
LEFT JOIN [ref].[RecordStatus] p16 ON p15.[RecordStatusKey] = p16.[RecordStatusKey]
LEFT JOIN [ref].[Severity] p17 ON p15.[SeverityKey] = p17.[SeverityKey]
LEFT JOIN [dim].[SupplierTier] p18 ON b.[SupplierTierKey] = p18.[SupplierTierKey]
LEFT JOIN [ref].[RecordStatus] p19 ON p18.[RecordStatusKey] = p19.[RecordStatusKey]
GO

